/**
 * Persistance du modèle typé de l'Atelier (`@parcours/atelier-model`, contrat `modele-atelier/1`) dans les tables
 * `atelier_*` (cahier des charges §5.5). Lecture complète ou par niveau, écriture par différentiel (seules les
 * entrées changées sont réécrites, à partir du même instantané différentiel qui sert d'inverse), remplacement
 * complet à l'import. Le modèle en mémoire est l'état sur lequel les réducteurs purs s'exécutent ; la base n'est
 * jamais modifiée par une route hors du service de commandes (R9).
 */
import { and, eq, inArray } from "drizzle-orm";
import type { Calque, Definition, Groupe, ModeleAtelier, Niveau, OccurrenceQuelconque, Probleme, Reference, Relation } from "@parcours/atelier-model";
import { differentiel, modeleVide } from "@parcours/atelier-model";
import type { db } from "../db/client.js";
import { atelierCalques, atelierDefinitions, atelierGroupes, atelierNiveaux, atelierObjets, atelierProblemes, atelierReferences, atelierRelations, atelierSite } from "../db/schema.js";

export const atelierVariants = pgTable("atelier_variants", {
  projectId: text("project_id").primaryKey().references(() => projects.id, { onDelete: "cascade" }),
  parentId: text("parent_id").notNull().references(() => projects.id, { onDelete: "cascade" }),
  nom: text("nom").notNull(),
  /** Révision du tronc au moment de la bifurcation. */
  forkRevision: integer("fork_revision").notNull(),
  /** Révision de la variante juste après la bifurcation (son journal propre commence après). */
  baseRevision: integer("base_revision").notNull(),
  forkEmpreinte: text("fork_empreinte").notNull(),
  statut: text("statut").$type<"ouverte" | "fusionnee">().notNull().default("ouverte"),
  fusionRevision: integer("fusion_revision"),
  fusionAt: timestamp("fusion_at", { withTimezone: true }),
  /** Dernière mise à jour de la variante depuis le tronc (D-136) : révision du tronc rejouée jusque-là. */
  syncRevision: integer("sync_revision"),
  authorId: text("author_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
});

this.version(1).stores({ outbox: "id, projectId", modelCache: "projectId" });
this.version(2).stores({ outbox: "id, projectId", modelCache: "projectId", keyValue: "key" });
this.version(3).stores({ outbox: "id, projectId", modelCache: "projectId", keyValue: "key", lots: "id, projectId, ordre" });
// Lot 4 (bascule) : la file clé / valeur de l'ancien moteur disparaît ; le cache de modèle change de forme (vidé).
this.version(4)
  .stores({ outbox: null, modelCache: "projectId", keyValue: "key", lots: "id, projectId, ordre" })
  .upgrade((tx) => tx.table("modelCache").clear());
